//! The module augmentation that types `@supatype/client` for one project's schema.
//!
//! Moved here from `packages/cli/src/augmentation-generator.ts`, which had a second
//! reading of the AST: its own column resolution, its own nullability rules and its own
//! scalar mapping. Two implementations of "what shape is this column" is the failure this
//! codebase has already paid for, so this one calls the same emitters as `types.rs`. The
//! two generated files now differ only in their wrapper.
//!
//! **Why an augmentation and not another exported type.** `createClient()` should be typed
//! from the project's schema without the caller passing a generic. Declaring the shapes
//! into `@supatype/client`'s own `SupatypeModels` interface is what does that: the file is
//! part of the project's program, so the augmentation applies wherever the client is
//! imported.

use super::types::{emit_fields, emit_shared_types, Mode};
use crate::parser::ast::{ModelAst, SchemaAst};
use anyhow::Result;

/// Render the client augmentation for `ast`.
pub fn generate(ast: &SchemaAst) -> Result<String> {
    let mut out = String::from("// Generated by supatype-engine. Do not edit manually.\n\n");
    emit_shared_types(ast, &mut out);

    out.push_str("declare module \"@supatype/client\" {\n");
    out.push_str("  interface SupatypeModels {\n");
    // In declaration order, the same as `types.rs`. The AST keeps what `schema/index.ts`
    // says, and two generated files describing the same tables should not disagree about
    // the order of them.
    for model in &ast.models {
        emit_model(model, &mut out);
    }
    out.push_str("  }\n");
    out.push_str("}\n\n");

    // Without this the file is a script, not a module, and `declare module` in a script is
    // a declaration of an ambient module rather than an augmentation of a real one: it
    // would replace `@supatype/client`'s types instead of adding to them.
    out.push_str("export {}\n");

    Ok(out)
}

fn emit_model(model: &ModelAst, out: &mut String) {
    let indent = "        ";
    out.push_str(&format!("    {}: {{\n", quote_key(model.table_name())));

    for (label, mode) in [
        ("Row", Mode::Row),
        ("Insert", Mode::Insert),
        ("Update", Mode::Update),
    ] {
        out.push_str(&format!("      {label}: {{\n"));
        emit_fields(model, mode, out, indent);
        out.push_str("      }\n");
    }

    out.push_str("    }\n");
}

/// An object key, quoted only where it has to be.
fn quote_key(key: &str) -> String {
    let valid = !key.is_empty()
        && key
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && key
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if valid {
        key.to_string()
    } else {
        serde_json::to_string(key).unwrap_or_else(|_| format!("\"{key}\""))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SCHEMA: &str = r#"{
        "astVersion": 2,
        "models": [
            {
                "name": "Event",
                "fields": {
                    "id": {"kind": "uuid", "required": true, "primaryKey": true,
                           "default": {"kind": "genRandomUuid"}},
                    "title": {"kind": "text", "required": true},
                    "status": {"kind": "enum", "required": true,
                               "values": ["draft", "published"], "default": "draft"},
                    "price": {"kind": "money", "required": false},
                    "organiser": {
                        "kind": "relation", "cardinality": "belongsTo", "target": "Organiser",
                        "required": true, "annotations": {"db": {"foreignKey": "organiser_id"}}
                    },
                    "speakers": {"kind": "relation", "cardinality": "hasMany", "target": "Speaker"}
                },
                "annotations": {"db": {"tableName": "event"}}
            },
            {
                "name": "Organiser",
                "fields": {
                    "id": {"kind": "uuid", "required": true, "primaryKey": true,
                           "default": {"kind": "genRandomUuid"}},
                    "name": {"kind": "text", "required": true}
                },
                "annotations": {"db": {"tableName": "organiser"}}
            },
            {
                "name": "Speaker",
                "fields": {"id": {"kind": "uuid", "required": true, "primaryKey": true}},
                "annotations": {"db": {"tableName": "speaker"}}
            }
        ]
    }"#;

    fn rendered() -> String {
        let ast: SchemaAst = serde_json::from_str(SCHEMA).expect("the fixture parses");
        generate(&ast).expect("renders")
    }

    fn assert_contains(haystack: &str, needle: &str) {
        assert!(
            haystack.contains(needle),
            "expected:\n  {needle}\ngot:\n{haystack}"
        );
    }

    #[test]
    fn it_augments_the_client_rather_than_exporting_a_type() {
        let out = rendered();
        assert_contains(&out, "declare module \"@supatype/client\" {");
        assert_contains(&out, "interface SupatypeModels {");
    }

    /// A `declare module` in a script replaces the module instead of augmenting it, and a
    /// file with no import or export is a script.
    #[test]
    fn it_is_a_module_so_the_augmentation_augments() {
        assert!(
            rendered().trim_end().ends_with("export {}"),
            "the file must be a module"
        );
    }

    /// The first of the two defects section 10 names. A required relation's column is `NOT NULL`,
    /// and typing it nullable makes the generated file contradict the schema it came from,
    /// while looking like the safer choice.
    #[test]
    fn a_required_relation_is_not_nullable() {
        let out = rendered();
        assert_contains(&out, "organiser_id: string\n");
        assert!(
            !out.contains("organiser_id: string | null"),
            "a required foreign key is NOT NULL:\n{out}"
        );
    }

    /// The second. A column the database fills must not be demanded on insert, whatever
    /// kind it is: an enum with a default was demanded while a text column with one was not.
    #[test]
    fn any_column_with_a_default_is_optional_on_insert() {
        let out = rendered();
        let insert = out
            .split("Insert: {")
            .nth(1)
            .expect("an Insert block")
            .split("}")
            .next()
            .expect("its body");
        assert_contains(insert, "status?:");
        assert_contains(insert, "id?:");
        assert_contains(insert, "title: string");
    }

    /// Only the side holding the key has a column here. A `hasMany` keeps its key on the
    /// other table, so describing one would describe a column that does not exist.
    #[test]
    fn an_inverse_relation_contributes_no_column() {
        assert!(
            !rendered().contains("speakers"),
            "a hasMany has no column on this table"
        );
    }

    /// Money is `NUMERIC(19,4)`, and the exact value is the point.
    #[test]
    fn money_is_an_exact_string() {
        assert_contains(&rendered(), "price: string | null");
    }

    /// Row says what a read returns, Update says what a write may set.
    #[test]
    fn row_demands_what_update_leaves_optional() {
        let out = rendered();
        assert_contains(&out, "        title: string\n");
        assert_contains(&out, "        title?: string\n");
    }

    /// Reordering the schema is a change the author made on purpose, and the generated file
    /// shows it. Alphabetising would have hidden it while claiming to be tidier.
    #[test]
    fn tables_follow_the_order_the_schema_declares() {
        let ast: SchemaAst = serde_json::from_str(SCHEMA).expect("parses");
        let out = generate(&ast).expect("renders");
        let event = out.find("    event: {").expect("event");
        let organiser = out.find("    organiser: {").expect("organiser");
        assert!(event < organiser, "Event is declared first: {out}");

        let mut reversed = ast.clone();
        reversed.models.reverse();
        let flipped = generate(&reversed).expect("renders");
        assert!(
            flipped.find("    organiser: {") < flipped.find("    event: {"),
            "and reversing the schema reverses the file: {flipped}"
        );
    }

    #[test]
    fn a_table_name_that_is_not_an_identifier_is_quoted() {
        let awkward = SCHEMA.replace(r#""tableName": "speaker""#, r#""tableName": "order-items""#);
        let ast: SchemaAst = serde_json::from_str(&awkward).expect("parses");
        assert_contains(&generate(&ast).expect("renders"), "    \"order-items\": {");
    }

    #[test]
    fn it_emits_no_any_and_nothing_outside_ascii() {
        let out = rendered();
        assert!(!out.contains(": any"), "no `any`");
        assert!(out.is_ascii(), "plain ASCII");
    }
}
